4633	void CodeGenModule::EmitGlobal(GlobalDecl GD) {
4634	  const auto *Global = cast<ValueDecl>(GD.getDecl());
4635	
4636	  // Weak references don't produce any output by themselves.
4637	  if (Global->hasAttr<WeakRefAttr>())
4638	    return;
4639	
4640	  // If this is an alias definition (which otherwise looks like a declaration)
4641	  // emit it now.
4642	  if (Global->hasAttr<AliasAttr>()) {
4643	    if (shouldSkipAliasEmission(*this, Global))
4644	      return;
4645	    return EmitAliasDefinition(GD);
4646	  }
4647	
4648	  // IFunc like an alias whose value is resolved at runtime by calling resolver.
4649	  if (Global->hasAttr<IFuncAttr>())
4650	    return emitIFuncDefinition(GD);
4651	
4652	  // If this is a cpu_dispatch multiversion function, emit the resolver.
4653	  if (Global->hasAttr<CPUDispatchAttr>())
4654	    return emitCPUDispatchDefinition(GD);
4655	
4656	  // If this is CUDA, be selective about which declarations we emit.
4657	  // Non-constexpr non-lambda implicit host device functions are not emitted
4658	  // unless they are used on device side.
4659	  if (LangOpts.CUDA) {
4660	    assert((isa<FunctionDecl>(Global) || isa<VarDecl>(Global)) &&
4661	           "Expected Variable or Function");
4662	    if (const auto *VD = dyn_cast<VarDecl>(Global)) {
4663	      if (!shouldEmitCUDAGlobalVar(VD))
